def split_overhead_fraction(p, hw, cfg) -> float:
    """Per-split fixed cost (pipeline fill/drain + serial fix-up) relative to the K iterations one split runs. Larger is worse."""
    iters = max(1, math.ceil(p.K / max(1, cfg.tile_k * max(1, cfg.split_k))))
    return min(4.0, (cfg.stages + 1.0) / iters)

def sm_idle_fraction(p, hw, cfg) -> float:
    """Fraction of SMs that receive no CTA at all (occupancy-independent). Larger is worse."""
    ctas = math.ceil(p.M / max(1, cfg.tile_m)) * math.ceil(p.N / max(1, cfg.tile_n)) * max(1, cfg.split_k)
    return max(0.0, 1.0 - ctas / max(1.0, float(hw.sm_count)))

def serial_fixup_traffic_ratio(p, hw, cfg) -> float:
    """Serial split-K partial-tile round trips relative to compulsory operand+output bytes. Larger is worse."""
    if cfg.split_k_mode != "serial" or cfg.split_k <= 1:
        return 0.0
    fix = 2.0 * (cfg.split_k - 1) * p.M * p.N * p.acc_bytes_per_element
    base = (p.M * p.K + p.K * p.N + p.M * p.N) * p.bytes_per_element
    return fix / max(1.0, base)
